class Solution {
public:
    vector<int> decode(vector<int>& encoded) {
        int n = encoded.size() + 1;

        int total_xor = 0;
        for (int i = 1; i <= n; i++) {
            total_xor ^= i;
        }

        int xor_without_first = 0;
        for (int i = 1; i < n - 1; i += 2) {
            xor_without_first ^= encoded[i];
        }

        vector<int> perm(n);
        perm[0] = total_xor ^ xor_without_first;

        for (int i = 1; i < n; i++) {
            perm[i] = perm[i - 1] ^ encoded[i - 1];
        }

        return perm;
    }
};
